package com.luminor.tavernquest.di
import android.content.Context;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.FirebaseFirestore;import com.google.firebase.storage.FirebaseStorage;import com.google.firebase.functions.FirebaseFunctions;import com.luminor.tavernquest.data.local.preferences.SettingsDataSource;import dagger.Module;import dagger.Provides;import dagger.hilt.InstallIn;import dagger.hilt.android.qualifiers.ApplicationContext;import dagger.hilt.components.SingletonComponent;import javax.inject.Singleton
@Module @InstallIn(SingletonComponent::class) object StorageModule{@Provides fun settings(@ApplicationContext c:Context)=SettingsDataSource(c);@Provides @Singleton fun firebaseAuth()=FirebaseAuthProvider(runCatching{FirebaseAuth.getInstance()}.getOrNull());@Provides @Singleton fun firebaseStorage()=FirebaseStorageProvider(runCatching{FirebaseStorage.getInstance()}.getOrNull());@Provides @Singleton fun firebaseFirestore()=FirebaseFirestoreProvider(runCatching{FirebaseFirestore.getInstance()}.getOrNull());@Provides @Singleton fun firebaseFunctions()=FirebaseFunctionsProvider(runCatching{FirebaseFunctions.getInstance("southamerica-east1")}.getOrNull())}
